mapper.select:
SELECT uf.id AS follow_id, uf.user_id AS user_id, uf.lecturer_id AS lecturer_id, uf.follow_time AS follow_time, l.lecturer_name AS lecturer_name, l.main_account AS main_account, l.main_account_id AS main_account_id, l.course_count AS course_count, l.follow_count AS follow_count, l.personal_intro AS personal_intro, l.cover_image_url AS cover_image_url, l.avatar_url AS avatar_url, l.lecturer_category_id AS category_id, l.lecturer_category_name AS category_name FROM user_lecturer_follow uf LEFT JOIN lecturer l ON uf.lecturer_id = l.id AND l.del_flag = 0 WHERE uf.del_flag = 0 AND uf.user_id = #{query.userId}
AND l.lecturer_name LIKE CONCAT('%', #{query.lecturerName}, '%')
ORDER BY uf.follow_time DESC
